    UserData = (const GHOST_DATA *)pGhostWnd->dwUserData;
    if (UserData)
    {
        Status = SafeProbeForRead(UserData, sizeof(GHOST_DATA), 1);
        if (!NT_SUCCESS(Status))
        {
            DPRINT1("Exception!\n");
            hwndTarget = NULL;
        }
        else
        {
            hwndTarget = UserData->hwndTarget;
        }
    }
    else
    {
        DPRINT("No user data\n");
        hwndTarget = NULL;
    }

    if (hwndTarget)
    {
        if (ValidateHwndNoErr(hwndTarget))
            return hwndTarget;

        DPRINT1("Not a window\n");
    }

    return NULL;
}
