   Status = STATUS_SUCCESS;
   if (pptDst && NT_SUCCESS(Status))
   {
      Status = SafeProbeForRead(pptDst, sizeof(POINT), 1);
   }
   if (pptSrc && NT_SUCCESS(Status))
   {
      Status = SafeProbeForRead(pptSrc, sizeof(POINT), 1);
